CREATE TABLE "lista_colaborativa" ("id" UUID NOT NULL, "dono_id" UUID NOT NULL, "titulo" VARCHAR(160) NOT NULL, "descricao" TEXT, "slug" VARCHAR(64) NOT NULL, "criada_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "lista_colaborativa_pkey" PRIMARY KEY ("id"));CREATE TABLE "lista_item" ("id" UUID NOT NULL, "lista_id" UUID NOT NULL, "midia_id" VARCHAR(255) NOT NULL, "adicionado_por" UUID, "observacao" TEXT, "criado_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "lista_item_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "lista_colaborativa_slug_key" ON "lista_colaborativa"("slug");CREATE INDEX "lista_colaborativa_dono_id_idx" ON "lista_colaborativa"("dono_id");CREATE UNIQUE INDEX "lista_item_lista_id_midia_id_key" ON "lista_item"("lista_id", "midia_id");CREATE INDEX "lista_item_lista_id_idx" ON "lista_item"("lista_id");ALTER TABLE "lista_colaborativa" ADD CONSTRAINT "lista_colaborativa_dono_id_fkey" FOREIGN KEY ("dono_id") REFERENCES "usuario"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "lista_item" ADD CONSTRAINT "lista_item_lista_id_fkey" FOREIGN KEY ("lista_id") REFERENCES "lista_colaborativa"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "lista_item" ADD CONSTRAINT "lista_item_adicionado_por_fkey" FOREIGN KEY ("adicionado_por") REFERENCES "usuario"("id") ON DELETE SET NULL ON UPDATE CASCADE;